<?php require 'includes/db.php'; $stmt = $pdo->query('SELECT id, name FROM countries WHERE is_active = 1'); $countries = $stmt->fetchAll(); foreach($countries as $c) { $cid = $c['id']; $cname = $c['name']; $countStmt = $pdo->prepare('SELECT COUNT(*) FROM universities WHERE country_id = ?'); $countStmt->execute([$cid]); $count = $countStmt->fetchColumn(); if($count < 5) { for($i = $count + 1; $i <= 5; $i++) { $ins = $pdo->prepare('INSERT INTO universities (country_id, name, qs_ranking, is_active) VALUES (?, ?, ?, 1)'); $ins->execute([$cid, 'University of ' . $cname . ' ' . $i, 'Top 500']); } echo 'Inserted ' . (5 - $count) . ' universities for ' . $cname . PHP_EOL; } }
